tasks('opening',start,'r1bqkbnr/pppp1ppp/2n5/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 2 3',[
['Weiß beginnt. Spiele einen guten ersten Zug. Welche Figur kann danach ins Spiel kommen?','e2–e4 und d2–d4 besetzen die Mitte und öffnen Wege für Läufer und Dame. Auch c2–c4, Sg1–f3, Sb1–c3, e2–e3, d2–d3, g2–g3, b2–b3 und f2–f4 sind gute Eröffnungszüge. Randzüge wie a2–a3 oder h2–h4 bringen kaum eine Figur ins Spiel.',null,['e2e4','d2d4','c2c4','g1f3','b1c3','e2e3','d2d3','g2g3','b2b3','f2f4']],
['Nach 1. e4 e5: Welche zentralen Felder greift Sg1–f3 an?','d4 und e5. Sf3 entwickelt eine Leichtfigur und greift den Bauern e5 an.','rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2',['g1f3']],
['Schwarz am Zug. Sf3 greift e5 an. Mit welchem Entwicklungszug deckt Schwarz den Bauern?','Sb8–c6 deckt e5 und entwickelt eine Figur. Auch Lf8–d6 deckt e5, versperrt aber den Bauern d7. d7–d6 deckt ebenfalls, entwickelt aber keine Figur.','rnbqkbnr/pppp1ppp/8/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R b KQkq - 1 2',['b8c6']],
['Nach 1. e4 e5 2. Sf3 d6: Ist Sf3xe5 ein Bauerngewinn?','Nein. Nach Sxe5 schlägt d6xe5 zurück. Weiß gibt einen Springer für einen Bauern.','rnbqkbnr/ppp2ppp/3p4/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 0 3',[]],
['Nach 1. d4 d5: Vergleiche Sg1–f3 und Sg1–h3. Welcher Zug wirkt auf die Mitte?','Sf3 deckt d4 und kontrolliert e5. Sh3 erreicht kein Zentrumsfeld. Ein Springer am Rand wirkt weniger.','rnbqkbnr/ppp1pppp/8/3p4/3P4/8/PPP1PPPP/RNBQKBNR w KQkq - 0 2',['g1f3']],
['Nach 1. e4 c5: Spielt acht Halbzüge. Erklärt je einen Entwicklungszug und eine gegnerische Drohung.','Beispiel: 2. Sf3 (Springer zur Mitte, deckt d4) d6 3. d4 (Bauer in die Mitte, greift c5 an) cxd4 4. Sxd4 (Springer zentral) Sf6 (Entwicklung, greift e4 an). Jede legale Folge zählt, wenn jeder Entwicklungszug mit Figur und Feld begründet und ein gegnerischer Angriff benannt wird.','rnbqkbnr/pp1ppppp/8/2p5/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2',[]],
['Nach 1. e4 e5 2. Sf3 Sc6: Nenne einen legalen Entwicklungszug und prüfe eine Antwort.','Beispiel Lf1–c4, Sg8–f6. Beide legal; Lc4 entwickelt den Läufer und richtet ihn auf f7. Kein erzwungener Gewinn behauptet.',null,['f1c4','f1b5','b1c3','d2d4']]]);
