tasks('rookend',rook,'2r3k1/5pp1/7p/8/8/6P1/5P1P/3R2K1 w - - 0 1',[
['Weiß am Zug. Prüfe zuerst beide Grundreihen: Kann ein König dort mattgesetzt werden?','Nein. h3 und h6 geben beiden Königen ein Fluchtfeld (Luft) auf h2 und h7. Erst wenn die Grundreihe sicher ist, lohnt sich ein aktiver Turmzug.',null,[]],
['Vergleiche Ta7 und Ta2. Welcher Turm ist aktiver? Zeige die angegriffenen Felder.','Ta7 steht auf der 7. Reihe und greift f7 an. Ta2 deckt nur die eigene 2. Reihe und ist passiv.','1r4k1/5pp1/7p/8/8/6PP/5P2/R5K1 w - - 0 1',['a1a7']],
['Weiß hat Ta7 gespielt. Welche Verteidigung von f7 ist passiv, welche Antwort sucht Gegenspiel?','Tf8 oder Kf8 decken f7, binden Schwarz aber an die Verteidigung. Tb2 greift f2 an und schafft Gegenspiel. Beide Ideen am Brett prüfen.','1r4k1/R4pp1/7p/8/8/7P/5PP1/6K1 b - - 1 1',['b8b2','b8f8','g8f8']],
['Nach 1. Ta7 Tb1+: Wohin kann der weiße König? Ist er sicher?','Kh2 ist der einzige Zug. Das Feld ist frei, weil der Bauer schon auf h3 steht. Ohne h3 wäre Tb1 Matt.','6k1/R4pp1/7p/8/8/7P/5PP1/1r4K1 w - - 2 2',['g1h2']],
['Nach 1. Ta7 Tf8: Vergleicht die beiden Türme. Wer bestimmt das Spiel?','Der weiße Turm a7 greift an und bindet. Der schwarze Turm f8 muss f7 decken. Aktivität heißt: Der Gegner muss reagieren.','5rk1/R4pp1/7p/8/8/7P/5PP1/6K1 w - - 2 2',[]],
['Andere Stellung: Weiß spielt 1. Tb7. Was antwortet Schwarz? Warum ist der aktive Zug hier ein Fehler?','1...Ta1+ 2. Tb1 Txb1#. Ohne Luft ist die eigene Grundreihe schwach. Merksatz: Erst Luft, dann Aktivität (zum Beispiel vorher h3).','r5k1/5ppp/8/8/8/8/5PPP/1R4K1 w - - 0 1',['h2h3','g2g3']],
['Weiß am Zug. Wähle zwischen Td7 und Td2. Prüfe vorher die eigene Grundreihe und eine schwarze Antwort.','Td7 ist aktiv: 7. Reihe, Angriff auf f7. Nach Tc1+ flieht der König mit Kg2, weil g3 schon gezogen ist. Td2 ist sicher, aber passiv. Bewertet wird die Begründung mit Grundreihe und Gegenantwort.',null,['d1d7']]]);
