ph.check=r[2];
if(name.startsWith('Einstieg')){put(ph,training.slice(0,1));ph.goal='Vorwissen und erste Vermutung zur Leitfrage sichtbar machen.';if(!ph.teacher.includes('Fachliche Leitfrage:'))ph.teacher+=' Fachliche Leitfrage: „'+r[0]+'“'+(s.entryType==='informative'?' Die Regel an Aufgabe 1 gemeinsam anwenden.':' Erst jede Person kurz selbst entscheiden lassen; keine gemeinsame Lösung vorwegnehmen.');ph.learners='Betrachte '+label(training.slice(0,1))+'. Zeige oder nenne eine erste Entscheidung und deinen Grund. Eine Vermutung darf später geändert werden.';ph.result='Erste Entscheidungen und eine offene Leitfrage; noch kein gemeinsamer Merksatz.';const idx=plan.sessions.indexOf(s);if(idx>0){const prev=plan.sessions[idx-1],pd=D.data[prev.topic||plan.settings.topic],recall=s.recall||{title:pd?.title||'letzte Stunde',text:pd?.explain||''};if(!ph.teacher.includes('Rückblick, etwa'))ph.teacher='Rückblick, etwa eine Minute: Ohne Vorlage abrufen lassen, was wir in „'+recall.title+'“ herausgefunden haben. Erwartung: '+recall.text+' Erst danach zum neuen Thema. '+ph.teacher;ph.learners='Zuerst ohne Vorlage: Nenne und zeige am Brett, was du letzte Stunde über „'+recall.title+'“ gelernt hast. Danach: '+ph.learners;ph.result='Abgerufene Erkenntnis der letzten Stunde; '+ph.result}}
if(name==='Erarbeitung'){put(ph,training.slice(0,2));ph.teacher='An '+label(training.slice(0,1))+' den Denkweg laut vormachen: '+r[1]+'. Vor dem entscheidenden Schritt stoppen und die Kinder ergänzen lassen. Danach '+label(training.slice(1,2))+' gemeinsam prüfen; Hilfen zurücknehmen. Typischer Stolperstein: '+d.error;ph.learners='Ergänze den fehlenden Prüfschritt. Erkläre am zweiten Beispiel, warum die Entscheidung gilt. Stelle eine Warum-Frage.';ph.result='Ein begründet gelöstes Modell und ein mit abnehmender Hilfe geprüftes zweites Beispiel.';ph.social=plan.settings.group>1?'Plenum mit eigener Denkzeit':'Einzelarbeit mit Anleitung'}
