const minimum=phases.reduce((n,ph)=>n+mins(ph),0);if(minimum<=s.duration){let left=s.duration-minimum;const work=phases.find(ph=>ph.name==='Übung');phases.forEach(ph=>ph.duration=mins(ph));if(s.duration>=30){for(const name of ['Erarbeitung','Anwendung','Lerncheck & Abschluss']){const ph=phases.find(x=>x.name===name);if(ph&&left>0){const take=Math.min(left,name==='Erarbeitung'?2:1);ph.duration+=take;left-=take}}}if(work)work.duration+=left;else phases.at(-2).duration+=left}
const practice=phases.find(ph=>ph.name==='Übung');if(practice){const m=C.methods.find(x=>x.id===practice.method);if(!phases.some(x=>x.name==='Erarbeitung')){put(practice,training.slice(0,5));practice.teacher='Kurzformat: an Aufgabe 1 einen Prüfschritt vormachen, Aufgabe 2 ergänzen lassen. Danach Aufgaben 3–5 nach Bedarf selbstständig bearbeiten. '+practice.teacher}if(m&&practice.duration<m.min){practice.method='exit';practice.teacher='Kurze Einzelaufgabe mit anschließendem begründeten Vergleich. '+practice.teacher.replace(m.instruction,'');practice.social=plan.settings.group>1?'Einzelarbeit, dann Partnervergleich':'Einzelarbeit'}}
