const own=(window.Curriculum.tactical.has(topic)?null:window.LessonRefinement.own[topic])||window.PlanningQuality.own[topic]||window.PlanningExtensions.exercises[topic]||window.LessonUnits.own[topic];
if(own)return own;
return puzzles.filter(p=>p.category===topic).sort((a,b)=>+a.Rating-+b.Rating).slice(0,6);
