function examples(m,puzzles){const r=rows.find(r=>r.id===m.id);if(!r)return [original(m,puzzles)];const list=pool(r.topic,puzzles);const chosen=list[r.index%list.length];const ordered=['errors','movement','sort','worked','repair','debate'].includes(m.id)?[chosen]:[...list.slice(r.index),...list.slice(0,r.index)];const seen=new Set();return ordered.filter(x=>{const key=x.fen||x.FEN||JSON.stringify(x.labyrinth);if(seen.has(key))return false;seen.add(key);return true}).map(x=>({...x,work:(x.work||'Finde den besten Zug und prüfe die gegnerische Antwort.').replace(/^Lerncheck: /,''),steps:r.steps.join(' '),source:x.source||'Lichess-Aufgabe, CC0.'}));}
// Allgemeine Schritte für den Stundenentwurf; die themenbezogenen Beispielschritte bleiben im Methodenkatalog.
const genericSteps={discussion:['Stellung zeigen und die Frage vorlesen.','Erst jedes Kind still denken lassen, dann zwei Antworten anhören.','Antworten am Brett prüfen und einen richtigen Grund festhalten.'],demo:['Den ersten Prüfschritt langsam zeigen und laut erklären.','Vor dem nächsten Schritt stoppen: „Wie geht es weiter?“','Ein Kind führt den Schritt aus, danach probieren alle selbst.'],errors:['Eine typische falsche Behauptung zur Aufgabe nennen.','Kinder zeigen am Brett, an welcher Stelle sie nicht stimmt.','Einen richtigen Zug finden und die passende Regel sagen.'],partner:['Beide überlegen zuerst allein.','Ein Kind schlägt einen Zug vor, das andere prüft die stärkste Antwort.','Die Folge nachspielen, dann Rollen tauschen.'],stations:['Drei Plätze mit je einer Aufgabe und verdeckter Lösung vorbereiten.','Paare bearbeiten jeden Platz in der vereinbarten Zeit und begründen ihre Entscheidung.','Gemeinsam eine schwierige Entscheidung klären.'],puzzle:['Aufgabe zeigen und Zugrecht nennen.','Jedes Kind sucht erst selbst einen Zug und eine Gegenantwort.','Lösung erst danach öffnen und den entscheidenden Gedanken erklären lassen.'],mini:['Start, Ziel und Sonderregeln am Brett zeigen.','Zwei Kinder planen und prüfen abwechselnd einen Zug.','Nach einem Versuch Rollen wechseln und einen besseren Weg suchen.'],movement:['Ein großes Brett mit Feldnamen auf dem Boden markieren.','Ein Kind geht einen angesagten Weg oder Zug ab.','Die anderen prüfen das Zielfeld; danach eine neue Person starten lassen.'],game:['Ein Paar betrachtet die Aufgabenstellung.','Abwechselnd eine richtige Beobachtung oder einen Zug nennen und am Brett zeigen.','Richtige Antworten gemeinsam sammeln, ohne Zeitdruck.'],tps:['Alle entscheiden 30 Sekunden allein.','Paare vergleichen ihre Gründe eine Minute lang.','Zwei Paare erklären der Gruppe ihre Entscheidung am Brett.'],jigsaw:['Drei Gruppen bekommen verschiedene Aufgaben; jedes Kind prüft die Lösung.','Neue Dreiergruppen bilden: aus jeder ersten Gruppe eine Person.','Jede Person erklärt ihre Aufgabe; die anderen spielen sie nach und fragen nach.'],comment:['Nur die Anfangsstellung der Aufgabe zeigen.','Vor jedem Lösungszug stoppen und einen Vorschlag mit Grund sammeln.','Gespeicherten Zug zeigen und seine Wirkung erklären lassen.'],create:['Eine Aufgabe der Stunde aufbauen.','Paare verändern eine Figur und schreiben eine passende Frage dazu.','Anderes Paar prüft die Frage und den Lösungsvorschlag; Unklares gemeinsam klären.'],tournament:['Paarungen, Startstellung und ein Beobachtungsziel vereinbaren.','In kurzen Runden spielen; bei Matt oder Remis neu beginnen und Farben tauschen.','Bei Zeitende stoppen, eine Entscheidung erklären und Partner wechseln.'],exit:['Eine neue Aufgabe zeigen und den Auftrag vorlesen.','Jedes Kind antwortet allein, mündlich oder auf einem Zettel.','Rückmelden, was schon gelingt und welcher Schritt noch geübt wird.'],compare:['Zwei ähnliche Stellungen nacheinander zeigen.','Kinder entscheiden jeweils und begründen ihre Entscheidung.','Den entscheidenden Unterschied an konkreten Feldern erklären lassen.'],sort:['Zwei Spalten „richtig“ und „falsch“ vorbereiten.','Kinder ordnen vorgegebene Züge oder Aussagen zur Aufgabe zu.','Jede Zuordnung am Brett begründen und bei Bedarf umsortieren.'],predict:['Den genannten Zug zunächst nicht ausführen.','Kinder zeigen Start- und Zielfeld und beschreiben das erwartete Brettbild.','Zug ausführen und die Vorhersage mit dem Brett vergleichen.'],reciprocal:['Ein Kind erklärt die Idee der Aufgabe.','Das andere stellt eine Warum-Frage dazu.','Am Brett prüfen und bei der nächsten Aufgabe Rollen tauschen.'],placemat:['Ein Blatt in vier Außenfelder und eine Mitte aufteilen.','Vier Kinder notieren oder zeichnen erst je eine eigene Idee.','Ideen am Brett prüfen; eine begründete Antwort in die Mitte schreiben.'],gallery:['Paare schreiben ihre Lösung samt Begründung auf ein Blatt.','Blätter auslegen; jedes Paar prüft eine andere Antwort am Brett.','Eine konkrete Rückfrage stellen, danach die eigene Lösung verbessern.'],silent:['Stellung zeigen, eine Minute Ruhe vereinbaren.','Alle notieren ihre Entscheidung und einen Beleg, ohne Figuren zu ziehen.','Erst danach vergleichen und am Brett prüfen.'],analogy:['Fragen: „Woher kommt der Name dieser Idee?“','Kinder zeigen am Brett, wo der Vergleich passt.','Gemeinsam klären, wo das Bild hilft und wo es nicht mehr stimmt.'],visual:['Stellung zehn Sekunden still betrachten lassen.','Kinder nennen nur sichtbare Merkmale: Figuren, Linien und Angriffe.','Daraus eine Frage ableiten, die sich am Brett prüfen lässt.'],journal:['Jedes Kind bekommt ein Blatt für Zugidee, Grund und offene Frage.','Eine Idee zur Aufgabe notieren oder zeichnen.','Am Brett prüfen und eine Korrektur ergänzen.'],coach:['Ein Kind entscheidet, das andere darf nur Fragen stellen.','Hilfsfrage nutzen, zum Beispiel: „Was droht?“ oder „Was war der letzte Zug?“','Entscheidung am Brett prüfen, bei der nächsten Aufgabe Rollen tauschen.'],retrieval:['Regel oder Merksatz abdecken und die Aufgabe zeigen.','Jedes Kind nennt die Regel aus dem Gedächtnis und wendet sie an.','Mit der Lösung abgleichen und einen fehlenden Punkt ergänzen.'],debate:['Zwei Zugvorschläge sammeln.','Je ein Paar erklärt einen Vorschlag und die mögliche Gegenantwort.','Beide Züge prüfen und gemeinsam eine begründete Entscheidung treffen.'],ladder:['Aufgabe zuerst ohne Tipp versuchen lassen.','Bei Bedarf eine Beobachtungsfrage geben, danach erst einen Figurenhinweis.','Nach jedem Tipp erneut selbst lösen lassen; Musterlösung zuletzt zeigen.'],question:['Stellung ohne vorgegebene Frage zeigen.','Jedes Paar formuliert eine Frage, die sich am Brett prüfen lässt.','Ein anderes Paar beantwortet sie mit einem konkreten Zugbeleg.'],checklist:['Die Prüfpunkte des Denkwegs nennen.','Kinder prüfen jeden Punkt und zeigen den Beleg.','Sobald ein Punkt nicht erfüllt ist, die Entscheidung mit diesem Grund erklären.'],contrast:['Zwei Stellungen zeigen, die sich in genau einem Merkmal unterscheiden.','Erst einzeln entscheiden lassen.','Kinder erklären, welches Merkmal den Unterschied macht.'],teachback:['Ein Kind liest die Regel und legt die Vorlage weg.','Es erklärt dem Partner die Regel an der Aufgabe.','Partner führt den Zug aus und fragt bei Unklarheit nach; danach wechseln.'],worked:['Ein Lösungsbeispiel zeigen, in dem ein Prüfschritt fehlt.','Kinder ergänzen den fehlenden Schritt und begründen ihn.','Danach eine neue Aufgabe ohne Vorlage lösen.'],vote:['Alle entscheiden verdeckt: ja oder nein?','Paare tauschen ihre Gründe aus und prüfen am Brett.','Erneut entscheiden und erklären, welcher Grund ausschlaggebend war.'],reverse:['Ein Ergebnis vorgeben, das die Stellung zeigen soll.','Paare bauen eine passende Stellung oder verändern genau eine Figur.','Anderes Paar testet den Entwurf; die Veränderung erklären lassen.'],secure:['Am schon bearbeiteten Beispiel einen Regelsatz sammeln.','Ein Kind zeigt einen konkreten Beleg für den Satz.','Alle übernehmen die geprüfte Regel als Satz oder Zeichnung.'],examplecounter:['Ein Beispiel und ein ähnliches Gegenbeispiel zeigen.','Kinder zeigen, was trotz ähnlicher Stellung anders ist.','Die Regel mit dem entscheidenden Unterschied formulieren.'],peercheck:['Beide lösen erst allein.','Lösungen tauschen und mit den genannten Kriterien prüfen: Entscheidung richtig? Beleg am Brett nachvollziehbar?','Eine begründete Rückmeldung geben; jedes Kind verbessert seine eigene Antwort.'],repair:['Eine eigene oder typische falsche Vermutung auswählen.','Kinder zeigen am Brett, warum sie nicht stimmt.','Einen richtigen Zug zeigen und die korrigierte Regel sagen.'],transfercard:['An die zuvor geprüfte Aufgabe erinnern.','Eine veränderte Aufgabe allein prüfen lassen.','Notieren oder sagen: „Was bleibt gleich, was ändert die Entscheidung?“'],confidence:['Vor dem Prüfen zeigen lassen: sicher, unsicher oder noch keine Idee.','Lösung notieren und den eigenen Beleg am Brett kontrollieren.','Sicherheit erneut einschätzen und einen Grund für eine Änderung nennen.'],labyrinth:['Start, Ziel und Hinderniszeichen gemeinsam klären.','Ein Kind plant einen Weg, das andere prüft jeden Abschnitt.','Weg nachspielen, Rollen tauschen und einen kürzeren Weg suchen.'],mental:['Stellung betrachten, Figuren stehen lassen.','Einen Zug nur vorstellen; Zielfeld und neue Wirkung sagen.','Zug am Brett ausführen und die Vorstellung kontrollieren.'],reconstruct:['Vorlage 20 Sekunden zeigen und dann abdecken.','Paare bauen die Stellung auf einem zweiten Brett nach.','Vorlage aufdecken, vergleichen und eine hilfreiche Merkhilfe nennen.'],dictation:['Ein Kind sieht das Diagramm, das andere nur ein leeres Brett.','Mit Farbe, Figur und Feld diktieren; nach jeder Ansage kurz warten.','Bretter vergleichen, fehlende Angaben ergänzen und Rollen tauschen.'],consultation:['Zwei Zweierteams an ein Brett setzen.','Vor jedem Zug nennt jedes Teammitglied eine Idee; das Team entscheidet.','Ziehende Person nach jedem Zug wechseln; nach vier Halbzügen eine Entscheidung besprechen.'],freeze:['Von der Aufgabenstellung aus spielen; Stopps vorher vereinbaren.','Nach zwei Halbzügen fragen: „Was greift der Gegner an?“','Eine Antwort prüfen, dann weiterspielen; nach dem zweiten Stopp auswerten.'],defender:['Den ersten Lösungszug der Aufgabe ausführen.','Ein Kind sucht legale Verteidigungen, das andere prüft Fortsetzungen.','Mit der gespeicherten Hauptvariante vergleichen; ungeklärte Nebenvarianten als offen festhalten.']};
for(const r of rows){const m=C.methods.find(m=>m.id===r.id);if(!m)continue;m.formalName=m.name;m.name=r.name;m.quickSteps=r.steps;m.genericSteps=genericSteps[r.id]||r.steps;m.topic=({mini:'moves',maze:'maze-basic'}[r.topic]||r.topic);m.instruction=m.genericSteps.map((s,i)=>(i+1)+'. '+s).join(' ');m.goal=m.genericSteps[0];m.material=m.needs.includes('space')?'Bodenbrett mit Feldnamen und freier Fläche.':m.needs.includes('paper')?'Beispielbilder ausdrucken; Papier und Stifte; Brett zum Prüfen.':m.id==='reconstruct'||m.id==='dictation'?'Vorlage und ein leeres Schachbrett pro Paar.':'Ein sichtbares Beispiel und ein Schachbrett pro Paar oder ein gemeinsames Demobrett.';m.simpleHint='Auftrag vorlesen. Zuerst die beteiligten Figuren und Felder zeigen lassen. Nur einen Prüfschritt auf einmal verlangen.';m.simpleObserve='Kann jedes Kind seine Entscheidung am Beispiel zeigen und mit einer Regel oder einem Zug begründen?';}
