window.EdmundResources=(()=>{const items=[{"id": "millionaire", "title": "Schach-Millionär", "url": "https://edmundbruns.github.io/bauerntaler/", "time": "10–15 Minuten", "prior": "Regeln sicher; Fragen laut Anbieter für etwa DWZ 800–1200.", "phase": "Wiederholung", "work": "Entscheidet erst allein. Vergleicht eure Gründe und wählt dann gemeinsam eine Antwort. Klärt nach drei Fragen eine unsichere Regel am Brett.", "easy": "Gib nur die erste Frage frei und lest gemeinsam.", "hard": "Begründet auch, warum eine andere Antwort falsch ist.", "methods": ["vote", "game", "exit", "confidence", "discussion"], "topics": ["fairplay", "notation", "opening"]}, {"id": "jeopardy", "title": "Schach-Jeopardy", "url": "https://edmundbruns.github.io/schachjepordy/", "time": "15–20 Minuten", "prior": "Sichere Grundregeln; laut Anbieter etwa DWZ 800–1200.", "phase": "Wiederholung in Teams", "work": "Bildet kleine Teams. Alle denken zuerst allein, dann beratet ihr euch. Zur gewählten Antwort gehört ein Grund oder ein Beispiel am Brett. Beendet die Auswahl nach der vereinbarten Zeit.", "easy": "Nur leichte Fragen auswählen und vorlesen.", "hard": "Vor der Antwort einen Gegenbeleg ausschließen.", "methods": ["game", "consultation", "discussion", "tps"], "topics": ["fairplay", "notation", "opening"]}, {"id": "openingquiz", "title": "Eröffnungs-Erkenner", "url": "https://edmundbruns.github.io/eroeffnungraten/", "time": "5–10 Minuten", "prior": "Grundstellung und erste Entwicklungszüge bekannt.", "phase": "Einstieg oder Wiederholung", "work": "Spielt die gezeigten Züge nach. Wählt die Eröffnung und erklärt anschließend die Idee eines Entwicklungszuges. Der Name allein genügt nicht.", "easy": "Stufe leicht wählen; eine Zugidee genügt.", "hard": "Zwei Entwicklungszüge und eine gegnerische Antwort vergleichen.", "methods": ["predict", "vote", "retrieval", "tps", "comment"], "topics": ["opening", "notation"]}, {"id": "monthly", "title": "Eröffnung des Monats", "url": "https://edmundbruns.github.io/eroeffnung/", "time": "10–15 Minuten", "prior": "Gangarten und Schachregel sicher.", "phase": "Erarbeitung und Anwendung", "work": "Betrachtet wenige Anfangszüge. Stoppt vor dem nächsten Zug, nennt eine eigene Idee und prüft die Gegenantwort. Spielt danach vier Halbzüge selbst weiter.", "easy": "Nur die ersten zwei Zugpaare bearbeiten.", "hard": "Einen Alternativzug mit konkreter Antwort vergleichen.", "methods": ["comment", "predict", "freeze", "consultation"], "topics": ["opening"]}, {"id": "strategy", "title": "Mittelspiel und Strategie", "url": "https://www.edmundbruns.com/schach/fortgeschrittene/mittelspiel/index.html", "time": "10–20 Minuten", "prior": "Sichere Regeln und erste Partieerfahrung.", "phase": "Stellung untersuchen", "work": "Wählt genau einen Grundsatz. Zeigt dazu ein Merkmal der Stellung, verbessert eine Figur und prüft eine gegnerische Antwort. Formuliert erst danach euren Plan.", "easy": "Nur die am wenigsten aktive Figur suchen.", "hard": "Zwei Pläne anhand konkreter Gegenantworten vergleichen.", "methods": ["placemat", "debate", "partner", "journal", "question"], "topics": ["planning", "rookend"]}, {"id": "diploma3", "title": "Ludgerus-Schachdiplom 3", "url": "https://ludgerusdiplom3.pages.dev/", "time": "15–25 Minuten für einen ausgewählten Lernabschnitt", "prior": "Sicheres Regelwissen; erste Erfahrung mit Partieplanung.", "phase": "Selbstständige Vertiefung", "work": "Wählt einen zur Stunde passenden Abschnitt. Findet einen Plan, spielt ihn am Brett und begründet ihn. Haltet am Ende eine hilfreiche Erkenntnis fest.", "easy": "Mit dem Lernbeispiel beginnen und mündlich erklären.", "hard": "Eine zweite Planidee prüfen und begründet verwerfen.", "methods": ["silent", "journal", "ladder", "coach", "partner"], "topics": ["planning", "opening"]}, {"id": "diploma4", "title": "Ludgerus-Schachdiplom 4", "url": "https://www.edmundbruns.com/schach/diplom4/index.html", "time": "15–25 Minuten für einen ausgewählten Lernabschnitt", "prior": "Passende Grundkenntnisse zum gewählten Thema.", "phase": "Selbstständige Übung", "work": "Wählt einen passenden Themenblock. Bearbeitet erst das Lernbeispiel, dann eine Übung und anschließend eine eigene Aufgabe mit Erklärung. Besprecht eine Entscheidung.", "easy": "Zuerst nur Beispiel und eine Übung nutzen.", "hard": "Eine Gegenantwort ohne Figurenbewegung berechnen.", "methods": ["stations", "silent", "ladder", "peercheck"], "topics": ["endgame", "fork", "pin", "discoveredAttack", "calculation"]}, {"id": "diploma5", "title": "Ludgerus-Schachdiplom 5 · Königsdiplom", "url": "https://www.edmundbruns.com/schach/diplom5/index.html", "time": "20–30 Minuten für einen ausgewählten Lernabschnitt", "prior": "Fortgeschrittene Kenntnisse; Voraussetzungen des gewählten Endspiels beachten.", "phase": "Vertiefung für Fortgeschrittene", "work": "Wählt ein bekanntes Endspielthema. Arbeitet am Beispiel den entscheidenden Plan heraus. Löst danach eine passende Übung und erklärt, warum die gegnerische Verteidigung nicht genügt.", "easy": "Voraussetzungen wiederholen und nur ein Modellbeispiel nutzen.", "hard": "Eine abweichende Verteidigung selbst untersuchen.", "methods": ["defender", "mental", "partner", "silent"], "topics": ["rookend", "endgame", "calculation"]}, {"id": "opposition", "title": "Emma erklärt: Opposition", "url": "https://app.lumi.education/run/W1JaWi", "time": "10–15 Minuten", "prior": "Königszüge und Bauernendspiele bekannt.", "phase": "Erklärimpuls und Brettübung", "work": "Seht euch die Erklärung an. Stoppt vor einem entscheidenden Königszug und nennt eure Vermutung. Stellt danach das Beispiel nach und prüft es mit vertauschtem Zugrecht.", "easy": "Nur die Stellung der beiden Könige betrachten.", "hard": "Ein Königsfeld verändern und die Folge neu berechnen.", "methods": ["demo", "predict", "compare", "contrast"], "topics": ["endgame"]}, {"id": "lucena", "title": "Emma erklärt: Die Lucena-Stellung", "url": "https://app.lumi.education/run/9mKziW", "time": "15–20 Minuten", "prior": "Turmendspiele und Bauernumwandlung sicher.", "phase": "Fortgeschrittenes Endspiel", "work": "Betrachtet das Modell und stoppt vor dem entscheidenden Turmzug. Erklärt seine Aufgabe. Baut die Stellung auf und spielt die gezeigte Verteidigung mit wechselnden Rollen nach.", "easy": "Die Modellfolge zunächst sichtbar nachspielen.", "hard": "Eine andere legale Verteidigung untersuchen.", "methods": ["demo", "comment", "predict", "defender"], "topics": ["rookend"]}, {"id": "kingactive", "title": "Emma erklärt: König aktiv einsetzen", "url": "https://app.lumi.education/run/_rmqam", "time": "10–15 Minuten", "prior": "Königszüge, Schachregel und einfache Endspiele bekannt.", "phase": "Endspielplan entwickeln", "work": "Nennt vor der Erklärung einen Plan für den König. Vergleicht ihn mit dem Beispiel und prüft eine gegnerische Antwort am Brett.", "easy": "Ein sicheres Zielfeld für den König zeigen.", "hard": "Zwei Königsrouten einschließlich Gegenwehr vergleichen.", "methods": ["predict", "partner", "journal", "coach"], "topics": ["endgame", "planning"]}, {"id": "trivial", "title": "Schach-Trivial", "url": "https://edmundbruns.github.io/schachtriva/", "time": "10–15 Minuten", "prior": "Grundregeln sicher; Spielanleitung gemeinsam lesen.", "phase": "Spielerische Wiederholung", "work": "Spielt in Paaren oder kleinen Teams. Vor jeder Antwort kurz beraten und einen Grund nennen. Nach der vereinbarten Zeit eine unsichere Frage gemeinsam klären.", "easy": "Fragen gemeinsam vorlesen.", "hard": "Zu einer Antwort eine eigene Beispielstellung zeigen.", "methods": ["game", "consultation", "discussion"], "topics": ["fairplay", "notation"]}];return {items,forMethod:id=>items.filter(x=>x.methods.includes(id)),forTopic:id=>items.filter(x=>x.topics.includes(id))};})();

window.KofferMethods=(()=>{const rows=[{"id": "koffer-figurenrechnen", "name": "Figurenwerte zusammenrechnen", "min": 8, "minGroup": 1, "topic": "moves", "index": 0, "steps": ["Lege einen weißen Turm, Läufer und zwei Bauern neben das Brett. Werte: Bauer 1, Springer 3, Läufer 3, Turm 5, Dame 9; der König bekommt keinen Tauschwert.", "Rechne die Werte zusammen. Stelle mit anderen Figuren dieselbe Summe dar.", "Vergleicht die Darstellungen: gleicher Rechenwert bedeutet nicht gleich starke Stellung."], "answer": "Turm 5 + Läufer 3 + zwei Bauern 2 = 10. Auch Dame 9 + Bauer 1 = 10.", "hint": "Nur Figurenwerte addieren, noch keine Stellungsbewertung verlangen."}, {"id": "koffer-kopfstand", "name": "Erst einen schlechten Plan finden, dann verbessern", "min": 10, "minGroup": 2, "topic": "endgame", "index": 2, "steps": ["Zeige die Bauernstellung. Frage: „Wie würde ich sicher zu spät beim Bauern ankommen?“", "Sammelt einen legalen Umweg. Kehrt die Idee um: Welcher direkte Weg hilft?", "Prüft die Verbesserung mit abwechselnden legalen Zügen. Ein guter Grundsatz garantiert noch keinen Fang."], "answer": "Nach a5 ist Schwarz am Zug. Ein legaler Umweg ist etwa Kg5: Der Weg zum Bauern wird länger. Der direkte Weg Ke5 ist besser, erreicht das Quadrat a5, d5, d8, a8 aber trotzdem nicht. Der Bauer wandelt um.", "hint": "Nur legale schlechte Züge verwenden, keine falschen Regeln einüben."}, {"id": "koffer-blindfinish", "name": "Die letzten Züge einer Kurzpartie im Kopf finden", "min": 10, "minGroup": 1, "topic": "notation", "index": 1, "steps": ["Spiele aus der Grundstellung e4 e5 Lc4 Sc6 Dh5 Sf6. Stoppe vor dem weißen Zug.", "Lass die Kinder den Mattzug zunächst nur ansagen und seine Wirkung erklären.", "Spielt den vorgeschlagenen Zug nach. Wer noch unsicher ist, darf das Brett die ganze Zeit ansehen."], "answer": "Dh5xf7 ist Matt. Die Dame f7 ist von Lc4 gedeckt; Schwarz kann weder ausweichen, schlagen noch dazwischenziehen.", "hint": "Zunächst nur einen Halbzug vorstellen. Erst später zwei oder drei ergänzen."}, {"id": "koffer-mattmemory", "name": "Gleiche Mattbilder finden und den Zug erklären", "min": 12, "minGroup": 2, "topic": "stalemate", "index": 1, "steps": ["Drucke drei verschiedene Mattaufgaben je zweimal aus. Mischt die sechs Karten und legt sie verdeckt aus.", "Ein Kind deckt zwei Karten auf. Bei gleichem Bild muss es zusätzlich den Mattzug zeigen.", "Richtig erklärt: Paar behalten und nächste Person ist dran. Sonst wieder verdecken. Ende, wenn alle Paare gefunden sind."], "answer": "Es zählen identische Diagrammpaare und ein korrekt geprüfter Mattzug. Nicht zwei beliebige Stellungen mit ähnlichen Figuren verbinden.", "hint": "Zum Einstieg alle Karten offen lassen. Paarzahl erst nach sicheren Antworten erhöhen."}, {"id": "koffer-motivewurf", "name": "Ein Motiv auslosen und eine Stellung dazu bauen", "min": 15, "minGroup": 2, "topic": "fork", "index": 0, "steps": ["Ordne die Würfelzahlen zu: 1 Gabel, 2 Fesselung, 3 Abzug, 4 Matt in eins, 5 Patt, 6 freie Wahl. Beide Könige müssen auf dem Brett sein.", "Würfelt einmal. Baut mit höchstens sechs Steinen ein Beispiel und schreibt Zugrecht, Frage und Lösung dazu.", "Ein anderes Paar prüft Regeln und Behauptung. Unklare Konstruktionen gemeinsam verbessern."], "answer": "Offene Konstruktionsaufgabe. Eine Gabel braucht zwei angegriffene Ziele; eine behauptete Gewinnfolge muss die Gegenantwort berücksichtigen.", "hint": "Nur bereits gelernte Motive auslosen; andere Zahlen neu würfeln."}, {"id": "koffer-tedtest", "name": "Zu einer Schachbehauptung abstimmen", "min": 8, "minGroup": 2, "topic": "castling", "index": 4, "steps": ["Zeige die Stellung und die Behauptung: „Weiß darf kurz rochieren.“ Alle stimmen zunächst verdeckt zu oder dagegen.", "Paare zeigen ihren Grund an einem Feld. Erst danach gemeinsam auflösen.", "Erneut abstimmen und erklären, welcher Beleg überzeugt hat."], "answer": "Nein: Der schwarze Turm auf g8 greift g1 an, das Zielfeld des weißen Königs. Die Rochade ist verboten.", "hint": "Drei Antwortkarten nutzen: stimmt, stimmt nicht, noch unsicher. Kein Kind muss sich vorführen lassen."}, {"id": "koffer-schreibkonferenz", "name": "Eine Stellung gemeinsam schriftlich untersuchen", "min": 12, "minGroup": 3, "topic": "planning", "index": 0, "steps": ["Gib jeder Dreiergruppe ein Diagramm und ein Blatt. Drei Minuten wird nicht gesprochen.", "A schreibt eine Zugidee mit Grund. B ergänzt eine gegnerische Antwort. C prüft und notiert eine Frage; danach rotieren.", "Zum Schluss dürft ihr sprechen: Spielt eine Variante nach und haltet eine geprüfte Erkenntnis fest."], "answer": "Beispiel Lg5 h6 Lh4 ist legal. Ein anderer legaler und begründeter Plan ist ebenfalls möglich. Offene Fragen als offen markieren.", "hint": "Satzanfänge anbieten: „Ich spiele …, weil …“ und „Der Gegner könnte …“."}, {"id": "koffer-rundreise", "name": "Von Aussage zu Aussage gehen und prüfen", "min": 15, "minGroup": 2, "topic": "pawn", "index": 0, "steps": ["Lege vier Aussagen im Raum aus. Jedes Paar erhält einen Antwortzettel. Aussagen: Bauern ziehen gerade; Bauern schlagen gerade; der Start-Doppelschritt darf über eine Figur gehen; Umwandlung kann zum Springer erfolgen.", "Paare gehen gemeinsam alle Plätze ab, notieren stimmt oder stimmt nicht und einen Beleg. Nach zwei Minuten zum nächsten Platz gehen.", "Löst gemeinsam auf. Eine falsche Aussage wird richtig formuliert."], "answer": "1 stimmt für normale Bauernzüge; 2 falsch, diagonal; 3 falsch, beide Felder müssen frei sein; 4 stimmt. Jede Aussage im passenden Regelkontext prüfen.", "hint": "Aussagen vorlesen und mündliche Antworten zulassen; freie Wege und ruhige Wechsel."}, {"id": "koffer-simultan", "name": "Eine Lehrkraft spielt an mehreren Brettern", "min": 20, "minGroup": 4, "topic": "opening", "index": 0, "steps": ["Beginne mit zwei oder drei Brettern und vereinbare: Die Kinder ziehen erst, wenn du am Brett stehst.", "Gehe reihum. Lass dir eine Zugidee erklären, spiele eine legale Antwort und gehe zum nächsten Brett.", "Nach zehn Minuten stoppen, ohne unfertige Partien zu werten. Jede Gruppe zeigt eine lehrreiche Entscheidung."], "answer": "Keine feste Gewinnlösung. Legale Züge, verständliche Begründungen und Beteiligung aller beobachten.", "hint": "Nur nutzen, wenn die Lehrkraft die Regeln sicher beherrscht. Kinder dürfen im Team beraten; starke Spielstärke ist keine Voraussetzung für die Kinder."}, {"id": "koffer-mattwettkampf", "name": "Mattaufgaben lösen und die Begründung vergleichen", "min": 12, "minGroup": 2, "topic": "mateIn1", "index": 0, "steps": ["Jedes Paar erhält dieselben drei Matt-in-eins-Aufgaben und acht Minuten Zeit. Richtiger Mattzug zählt einen Punkt, korrekte Erklärung einen weiteren.", "Alle denken erst allein, dann vergleicht das Paar. Prüft nach dem Zug Flucht, Schlagen und Dazwischenziehen.", "Nach acht Minuten gemeinsam auswerten. Ziel ist eine gründliche Lösung; Schnelligkeit gibt keine Zusatzpunkte."], "answer": "Für jede Aufgabe den gespeicherten Mattzug prüfen. Ohne legale Abwehr ist es Matt; ein Schach allein genügt nicht.", "hint": "Nur eine Aufgabe und eine Hilfe anbieten. Ergebnisse ohne öffentliche Rangliste rückmelden."}, {"id": "koffer-schachpuzzlebild", "name": "Ein zerschnittenes Schachbild zusammensetzen", "min": 10, "minGroup": 2, "topic": "promotion", "index": 3, "steps": ["Drucke das Beispieldiagramm aus und schneide es in vier große Teile. Lege ein vollständiges Lösungsbild verdeckt bereit.", "Paare setzen das Brett zusammen und erklären, woran sie Nachbarteile erkennen.", "Mit der Vorlage vergleichen. Danach im wiederhergestellten Bild den Bauern umwandeln."], "answer": "Das vollständige Originalbild ist die eindeutige Vorlage. Der schwarze Bauer d2 wandelt auf d1 um: d1=D, d1=T, d1=L und d1=S sind möglich.", "hint": "Zuerst nur zwei Teile schneiden. Feldnamen dürfen als Orientierung sichtbar bleiben."}, {"id": "koffer-knuffel", "name": "Mit Figurenwürfeln Punkte sammeln", "min": 15, "minGroup": 2, "topic": "exchange", "index": 0, "steps": ["Eigene Kurzvariante: fünf normale Würfel. 1=Bauer (1), 2=Springer (3), 3=Läufer (3), 4=Turm (5), 5=Dame (9), 6=Joker. Jedes Kind zeichnet fünf Kategorien: Bauer, Springer, Läufer, Turm, Dame.", "Reihum höchstens dreimal würfeln; passende Würfel dürfen liegen bleiben. Wähle dann eine noch freie Kategorie und zähle nur passende Figuren. Jeder Joker zählt einmal als gewählte Figur.", "Nach fünf Runden sind alle Kategorien gefüllt; unpassende Würfe bringen null. Addiert die fünf Ergebnisse. Höchste Summe gewinnt, bei Gleichstand gemeinsam gewonnen."], "answer": "Beispiel: 5,5,6,2,1 in Kategorie Dame: zwei Damen plus Joker = 27 Punkte. Keine Bonusfelder oder zusätzlichen Kombinationen in dieser Kurzvariante.", "hint": "Dies ist eine eigene vereinfachte Variante, nicht der Originalspielbogen. Figurenwerte sind Lernwerte, kein Königswert."}, {"id": "koffer-wuerfelschach", "name": "Die Figurenart für den nächsten Zug würfeln", "min": 15, "minGroup": 2, "topic": "opening", "index": 0, "steps": ["Eigene regelnahe Variante: 1=Bauer, 2=Springer, 3=Läufer, 4=Turm, 5=Dame, 6=König. Reguläre Grundstellung. Alle Schachregeln gelten weiterhin; rochieren zählt als Königszug.", "Vor jedem Zug würfeln und mit der gewürfelten Art einen legalen Zug machen. Gibt es keinen, erneut würfeln. Steht der König im Schach, nicht würfeln: eine beliebige legale Schachabwehr spielen.", "Matt und Patt beenden die Partie nach normalen Regeln. Nach zehn Minuten laufende Partie ohne Ergebniswertung stoppen und einen Zug erklären."], "answer": "In der Grundstellung können nur Bauern und Springer ziehen; andere Zahlen erfordern einen neuen Wurf. Der König wird niemals geschlagen.", "hint": "Eigene Variante, da die veröffentlichte Würfelanleitung das Spielende widersprüchlich beschreibt. Kein Sonderregelspiel im regulären digitalen Lehrbrett erzwingen."}, {"id": "koffer-feldbild", "name": "Nach Feldnamen ein Muster ausmalen", "min": 8, "minGroup": 1, "topic": "coordinates", "index": 0, "steps": ["Gib ein leeres Diagramm mit Feldnamen aus. Lies langsam a1, b2, c3, d4, e5, f6, g7, h8 vor.", "Kinder markieren jedes Feld. Nach je zwei Feldern kurz vergleichen.", "Das entstehende Muster benennen. Danach diktiert ein Kind eine andere Linie."], "answer": "Die acht Felder bilden die Diagonale a1–h8. Diese Übung trainiert Feldnamen, nicht das Schreiben vollständiger Züge.", "hint": "Linie zuerst, Reihe danach; bei Bedarf am Rand mit dem Finger mitgehen."}];
const C=window.PlannerCore,T=window.TeachingSupport;
const source='https://schachtraining.de/wp-content/uploads/iNGOLSTADT-SCHACHMETHODEN-Dillingen.pdf';
const dice='https://www.euroschach.de/media/products/schachwuerfel-anleitung.pdf';
const oldExamples=T.examples;
function ownPool(topic){return window.LessonRefinement.own[topic]||window.PlanningQuality.own[topic]||window.PlanningExtensions.exercises[topic]||window.LessonUnits.own[topic]||[]}
function examples(m,puzzles){const r=rows.find(x=>x.id===m.id);if(!r)return oldExamples(m,puzzles);let pool=ownPool(r.topic);if(!pool.length)pool=puzzles.filter(p=>p.category===r.topic).sort((a,b)=>+a.Rating-+b.Rating);let selected=[pool[r.index%pool.length]];
if(r.id==='koffer-mattwettkampf')selected=puzzles.filter(p=>p.category==='mateIn1').slice(0,3);if(r.id==='koffer-mattmemory')selected=[['6k1/5ppp/8/8/8/8/8/R5K1 w - - 0 1','Grundreihenmatt: Ta8#. Die eigenen Bauern versperren dem König die Flucht.'],['7k/8/5K2/8/8/8/8/6Q1 w - - 0 1','Dame mit König: Dg7#, die Dame ist vom König f6 gedeckt.'],['k7/7R/8/8/8/8/8/6RK w - - 0 1','Treppenmatt mit zwei Türmen: Tg8#. Der Turm h7 sperrt die 7. Reihe.']].map(([fen,answer],i)=>({id:'memory-'+i,fen,answer,checks:[]}));
if(r.id==='koffer-blindfinish')selected=[{fen:'r1bqkb1r/pppp1ppp/2n2n2/4p2Q/2B1P3/8/PPPP1PPP/RNB1K1NR w KQkq - 4 4',checks:['h5f7']}];
return selected.map(x=>({...x,steps:r.steps.join(' '),work:r.steps.join(' '),answer:x.answer||r.answer,source:'Eigene Unterrichtsumsetzung nach öffentlich beschriebener Grundidee. '+source}));}
for(const r of rows){const diceTopic=['koffer-knuffel','koffer-wuerfelschach','koffer-motivewurf'].includes(r.id);C.methods.push({id:r.id,name:r.name,en:r.name,formalName:'Spiel- und Bastelmethode',min:r.min,minGroup:r.minGroup,needs:r.id==='koffer-rundreise'?['paper','space']:['work'],topic:r.topic,level:['koffer-motivewurf','koffer-blindfinish','koffer-simultan','koffer-schreibkonferenz'].includes(r.id)?'Grundkenntnisse':'Anfänger',quickSteps:r.steps,instruction:r.steps.map((x,i)=>(i+1)+'. '+x).join(' '),goal:r.steps[0],prereq:r.hint,diff:'Einfacher: ein Beispiel gemeinsam. Anspruchsvoller: eine eigene Begründung oder Gegenidee prüfen.',material:r.id==='koffer-knuffel'?'Fünf Würfel, Papier und Stift pro Gruppe.':r.id==='koffer-wuerfelschach'?'Ein Würfel und ein echtes Schachbrett pro Paar.':'Schachbrett, ausgedruckte Beispieldiagramme, Papier und Stifte; bei Bildpuzzle Schere.',simpleHint:r.hint,simpleObserve:'Kann jedes Kind den Auftrag ausführen und einen passenden Grund nennen?',original:({'koffer-mattmemory':'Schach-Memory','koffer-schachpuzzlebild':'Das Schachpuzzle','koffer-knuffel':'Knuffelschach'})[r.id]||'',sourceUrl:diceTopic?dice:source,sourceNote:diceTopic?'Eigene Variante. Die genaue Abweichung steht in der Anleitung.':'Eigene Anleitung nach öffentlich beschriebener Grundidee. Keine Originalkarte des Methodenkoffers.',tabletopOnly:['koffer-knuffel','koffer-wuerfelschach','koffer-motivewurf','koffer-feldbild','koffer-schachpuzzlebild','koffer-simultan','koffer-rundreise','koffer-figurenrechnen'].includes(r.id)});}
T.examples=examples;T.example=(m,puzzles)=>examples(m,puzzles)[0];
// Vorhandene Verfahren mit ihrer Quelle verbinden, ohne Duplikate vorzutäuschen.
for(const id of ['consultation','errors','labyrinth','mental','vote']){const m=C.methods.find(x=>x.id===id);m.sourceUrl=source;m.sourceNote='Eigenständiges verwandtes Verfahren. Der Ablauf kann vom Originalkoffer abweichen.';}
const previous=C.generate;C.generate=(settings,puzzles)=>{const p=previous(settings,puzzles),m=C.methods.find(x=>x.id===settings.method&&x.id.startsWith('koffer-'));if(!m)return p;for(const s of p.sessions){const ph=s.phases.find(x=>x.name==='Übung');if(!ph)continue;if(ph.duration<m.min){ph.notes+=' Für die vollständige Methode mindestens '+m.min+' Minuten einplanen. Aktuell ist nur eine kurze thematische Einzelübung möglich.';continue}ph.method=m.id;const own=(s.topic||settings.topic)===m.topic;ph.teacher=own?'Nutze den Drei-Schritte-Ablauf aus der Methodenanleitung mit den zugeordneten Aufgaben. '+m.instruction:'Methode „'+m.name+'“ mit den Aufgaben dieser Stunde durchführen. Ablauf und Beispiel stehen im Methodenkatalog; das dortige Beispiel gehört zu einem anderen Thema und wird hier nicht verwendet. Erst allein bearbeiten, dann im Paar vergleichen und am Brett prüfen.';ph.notes+=' Beispiel und Stundenthema vorab abgleichen. Bei abweichendem Thema die Methode separat einsetzen.';ph.material=m.material;}return p};
return {rows,source};})();

