function genericHints(x,r,d){const steps=r[1].split('→').map(v=>v.trim());const first=(x.answer||'').split(/(?<=\.)\s/)[0];return ['Schau zuerst: '+steps[0]+'.','Typischer Stolperstein: '+d.error,'Lösungsanfang: '+first]}

