function scan(ph,teacher,learners,result){ph.scan_teacher=teacher;ph.scan_learners=learners;ph.scan_result=result}
const mazeRows={
'maze-basic':['Wie kommt der Turm um die Sperrfelder herum?','Start und Ziel zeigen → Sperrfelder markieren → Weg in geraden Stücken planen → jeden Abschnitt prüfen','Der Turm zieht nur gerade und kommt nicht durch Sperrfelder. Um ein Hindernis führt ein Richtungswechsel.','Gültiger Weg ohne Sperrfeld; zwei Richtungswechsel erklärt.','Einen erlaubten Turmweg finden und Richtungswechsel erklären.'],
'maze-build':['Warum darf der Turm hier nicht durch, der Springer aber schon?','Hindernisart benennen → Sperrfeld (×) oder Landeverbot (○)? → Linienfigur oder Springer? → Weg prüfen','Sperrfelder blockieren Wege, Landeverbote nur das Ziel. Der Springer springt über alles, landet aber nie auf × oder ○.','Gültiger Weg; bei jedem Hindernis die Art richtig benannt.','Den Unterschied zwischen Blockaden auf dem Weg (Sperrfelder) und verbotenen Zielfeldern (Landeverbote) bei Linienfiguren und Springer erkennen und anwenden.'],
'maze-deep':['Wann macht ein Schlag den Weg kürzer?','Kürzesten Weg ohne Schlag suchen → erlaubte Schläge prüfen → Wege vergleichen → Züge zählen','Ein erlaubter Schlag entfernt ein Hindernis und kann den Weg verkürzen. Gezählt wird jeder Zug.','Kürzester Weg gefunden und begründet, warum es nicht kürzer geht.','Einen möglichst kurzen Weg planen und begründen, wie ein erlaubter Schlag neue Wege öffnet.']};
const mazeNext={'maze-basic':'Figurenlabyrinth · Wege vergleichen (Springer und Landeverbote)','maze-build':'Figurenlabyrinth · Planen und Schlagen','maze-deep':'Kandidaten und Varianten'};
