s.goal=goal;s.success=[crit,'Vor jedem Zug die Hindernisart nennen.','Die Lerncheck-Aufgabe ohne Hilfe lösen.'];s.reserveFast='Knobelaufgabe: nachweisen, warum kein kürzerer Weg existiert. Danach ein eigenes Labyrinth für den Partner zeichnen.';s.reserveShort='Aufgabe 5 weglassen. Sicherung und Lerncheck beibehalten.';s.outlook='Nächste Stunde: '+mazeNext[t]+'.';s.diagnostic='Vorwissen im Einstieg prüfen: Zeige einen Turmweg von a1 nach a8 und zwei Felder, die der Springer von b1 erreicht.';
